SELECT customers.city, customers.segment, COUNT(CASE WHEN accounts.status = 'FROZEN' THEN 1 END) AS frozen_count, SUM(CASE WHEN accounts.account_type = 'SAVINGS' THEN accounts.balance ELSE 0 END) AS savings_balance FROM accounts RIGHT OUTER JOIN customers ON accounts.customer_id = customers.id WHERE LOWER(customers.name) LIKE '%enr%' GROUP BY customers.city, customers.segment ORDER BY savings_balance, city, segment LIMIT 5;
